{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C47"],
      "claim": "Ivabradine, which matches the query's benzazepinone lactam, propyl-linked tertiary amine, and dimethoxyaryl/benzocyclobutene scaffold, has an oral bioavailability close to 40% in healthy volunteers after hepatic first-pass metabolism, directly supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C53"],
      "claim": "A close structural analogue (Morgan similarity 0.6441) with the same benzazepinone/tertiary-amine/dimethoxyaryl core had an absolute oral bioavailability of 51.5 ± 17.8% (range 29–80%) in healthy volunteers, strongly supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Donepezil, a dimethoxyaryl basic amine without hydrogen-bond donors, has ~100% oral bioavailability in humans, showing that this chemotype can be highly bioavailable, though its lower similarity reduces weight.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Tetrabenazine, a dimethoxybenzoquinolizine tertiary amine, has very low oral bioavailability (mean 4.9%) due to first-pass metabolism; however, it lacks the amide/lactam and second dimethoxyaryl group of the query, limiting transferability.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C33"],
      "claim": "Almorexant, combining a dimethoxy-tetrahydroisoquinoline, amide, and basic amine, has an absolute oral bioavailability of 11.2% in healthy subjects, suggesting low F for some amide/amine/dimethoxyaryl combinations; low similarity to the query limits its weight.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is structurally ivabradine, a benzazepinone/benzocyclobutene tertiary amine with two dimethoxyaryl groups. Direct human pharmacokinetic data for ivabradine show oral bioavailability close to 40%, and a very close analogue (Morgan similarity 0.6441) shows absolute F of 51.5 ± 17.8% (range 29–80%). These high-F results outweigh the low-F evidence from tetrabenazine and almorexant, which are less structurally similar and lack the lactam/benzocyclobutene features. Therefore, F ≥ 20% is strongly supported.",
  "evidence_gaps": [
    "No exact-match experimental F record for the query in the provided cards, but the query appears to be ivabradine, for which human F ~40% is available.",
    "Some L2 records are apparent bioavailability or from animal models, reducing directness.",
    "Tetrabenazine has one outlier record (C46, ≥75%) conflicting with the majority low-F data, but the preponderance supports low F.",
    "The identity of 'compound 1' in C53/C45 is not fully specified; its SMILES indicates a close analogue rather than the exact query."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "high",
      "card_ids": ["C47", "C53", "C45"],
      "decision_effect": "changed",
      "direction": "supportive",
      "family": "ivabradine/compound 1"
    },
    {
      "applicability": "moderate",
      "card_ids": ["C55", "C50", "C46", "C51"],
      "decision_effect": "no_change",
      "direction": "contradictory",
      "family": "tetrabenazine additional"
    },
    {
      "applicability": "low",
      "card_ids": ["C48"],
      "decision_effect": "no_change",
      "direction": "contradictory",
      "family": "armepavine"
    },
    {
      "applicability": "low",
      "card_ids": ["C54", "C56"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "scoulerine/luteanin"
    },
    {
      "applicability": "low",
      "card_ids": ["C52", "C49"],
      "decision_effect": "no_change",
      "direction": "contradictory",
      "family": "verapamil"
    }
  ],
  "revision_action": "flip"
}

